import {describe, it, expect} from 'vitest';
import type {ListSessionsMessage, SessionListMessage, SessionSummaryFrame} from './messages.js';

// Validate that the new message types exist and have the right shapes
describe('message types for list_sessions', () => {
  it('ListSessionsMessage has the correct shape', () => {
    const msg: ListSessionsMessage = {type: 'list_sessions'};
    expect(msg.type).toBe('list_sessions');

    const withLimit: ListSessionsMessage = {type: 'list_sessions', limit: 10};
    expect(withLimit.limit).toBe(10);

    const withBefore: ListSessionsMessage = {
      type: 'list_sessions',
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
    };
    expect(withBefore.before).toEqual({updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'});
  });

  it('SessionSummaryFrame has the correct shape', () => {
    const frame: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:05:00.000Z',
      entryCount: 2,
    };
    expect(frame.sessionId).toBe('s1');
    expect(frame.createdAt).toBe('2026-01-01T00:00:00.000Z');
    expect(frame.updatedAt).toBe('2026-01-01T00:05:00.000Z');
    expect(frame.entryCount).toBe(2);
  });

  it('SessionListMessage has the correct shape', () => {
    const msg: SessionListMessage = {
      type: 'session_list',
      sessions: [
        {
          sessionId: 's1',
          createdAt: '2026-01-01T00:00:00.000Z',
          updatedAt: '2026-01-01T00:05:00.000Z',
          entryCount: 2,
        },
      ],
    };
    expect(msg.type).toBe('session_list');
    expect(msg.sessions).toHaveLength(1);
    expect(msg.sessions[0].sessionId).toBe('s1');
  });
});

